import unittest

from solution import required_template_fields


class RequiredTemplateFieldsTests(unittest.TestCase):
    def test_empty_literal_escaped_and_positional_fields(self):
        self.assertEqual(required_template_fields(""), ())
        self.assertEqual(required_template_fields("{{name}} {} {0} {12}"), ())

    def test_named_roots_first_occurrence_and_duplicates(self):
        template = "{account.name} {rows[0]} {account.id!r} {_private:>8} {rows[12].value}"
        self.assertEqual(
            required_template_fields(template),
            ("account", "rows", "_private"),
        )
        self.assertEqual(
            required_template_fields(template, ("rows",)),
            ("account", "_private"),
        )

    def test_all_supplied_and_extra_supplied_names(self):
        supplied = ["account", "rows", "unused"]
        before = list(supplied)
        result = required_template_fields("{account.name}-{rows[0]}", supplied)
        self.assertEqual(result, ())
        self.assertEqual(supplied, before)

    def test_plain_format_specification_is_supported(self):
        self.assertEqual(
            required_template_fields("value={value:>10.2f}, again={value!s}"),
            ("value",),
        )

    def test_nested_replacement_fields_in_spec_rejected(self):
        for template in ("{value:{width}}", "{value:>{width}.2f}", "{x:{}}"):
            with self.subTest(template=template):
                with self.assertRaises(ValueError):
                    required_template_fields(template)

    def test_invalid_braces_and_unsupported_field_syntax(self):
        invalid = [
            "{", "}", "text {name", "text name}",
            "{é}", "{account.é}", "{account.}", "{account..name}",
            "{rows[name]}", "{rows[-1]}", "{[0]}", "{a-b}",
        ]
        for template in invalid:
            with self.subTest(template=template):
                with self.assertRaises(ValueError):
                    required_template_fields(template)

    def test_non_string_template_rejected(self):
        for template in (None, b"{name}", 1, ["{name}"]):
            with self.subTest(template=template):
                with self.assertRaises(ValueError):
                    required_template_fields(template)

    def test_invalid_supplied_value_rejected_even_if_otherwise_unused(self):
        invalid_values = ("", "two words", "é", "9name", "a-b", 1, None)
        for value in invalid_values:
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    required_template_fields("literal text", ("valid", value))


if __name__ == "__main__":
    unittest.main()

